 22→function findDuplicateFileNames(files: File[]): string[] {
 23→  const seen = new Set<string>();
 24→  const duplicates = new Set<string>();
 25→  for (const file of files) {
 26→    if (seen.has(file.name)) {
 27→      duplicates.add(file.name);
 28→    }
 29→    seen.add(file.name);
 30→  }
 31→  return Array.from(duplicates);
 32→}
